package za.ac.cput.controller; import org.springframework.web.bind.annotation.*; import za.ac.cput.domain.Login; import za.ac.cput.service.LoginService; import java.util.List; @RestController @RequestMapping("/login") public class LoginController{private final LoginService service; public LoginController(LoginService service){this.service=service;} @PostMapping("/create") public Login create(@RequestBody Login x){return service.create(x);} @GetMapping("/read/{id}") public Login read(@PathVariable String id){return service.read(id);} @PutMapping("/update") public Login update(@RequestBody Login x){return service.update(x);} @DeleteMapping("/delete/{id}") public boolean delete(@PathVariable String id){return service.delete(id);} @GetMapping("/getAll") public List<Login> getAll(){return service.findAll();} }